/* ==========================================================
   SCIO EXPERT NETWORK
   n8n Form — Full Custom Theme
   ========================================================== */


/* ==========================================================
   1. GLOBAL VARIABLES
   ========================================================== */

:root {

  /* Scio palette */
  --scio-navy: #272b43;
  --scio-navy-hover: #343952;

  --scio-orange: #e58b45;
  --scio-orange-hover: #d77b36;

  --scio-bg: #f6f6f3;
  --scio-white: #ffffff;

  --scio-text: #292d41;
  --scio-muted: #747786;

  --scio-border: #dedfe4;
  --scio-border-hover: #bfc1ca;

  --scio-error: #c83f49;


  /* n8n form variables */
  --font-family:
    "Avenir Next",
    Inter,
    "Segoe UI",
    Helvetica,
    Arial,
    sans-serif;

  --font-weight-normal: 400;
  --font-weight-bold: 600;

  --font-size-body: 14px;
  --font-size-label: 14px;
  --font-size-input: 15px;

  --font-size-header: 34px;
  --font-size-paragraph: 15px;
  --font-size-subheader: 15px;

  --font-size-link: 13px;
  --font-size-error: 12px;
  --font-size-test-notice: 12px;

  --font-size-html-h1: 34px;
  --font-size-html-h2: 25px;
  --font-size-html-h3: 20px;
  --font-size-html-h4: 17px;
  --font-size-html-h5: 15px;
  --font-size-html-h6: 13px;


  /* Background / card */
  --color-background: #f6f6f3;

  --color-card-bg: #ffffff;
  --color-card-border: #e7e7e3;
  --color-card-shadow: rgba(28, 32, 50, 0.10);


  /* Header */
  --color-header: #272b43;
  --color-header-subtext: #747786;


  /* Inputs */
  --color-label: #34384d;

  --color-input-bg: #ffffff;
  --color-input-border: #dedfe4;
  --color-input-text: #292d41;

  --color-focus-border: #e58b45;


  /* Submit */
  --color-submit-btn-bg: #e58b45;
  --color-submit-btn-text: #ffffff;


  /* Links */
  --color-link: #d47834;
  --color-html-link: #d47834;
  --color-html-text: #464a5c;


  /* Misc */
  --color-error: #c83f49;
  --color-required: #e58b45;
  --color-clear-button-bg: #777a89;

  --color-test-notice-text: #86531d;
  --color-test-notice-bg: #fff8ee;
  --color-test-notice-border: #f0d2a7;


  /* Radius */
  --border-radius-card: 20px;
  --card-border-radius: 20px;

  --border-radius-input: 10px;
  --border-radius-clear-btn: 50%;


  /* Layout */
  --container-width: 660px;

  --padding-container-top: 52px;

  --padding-card: 44px;
  --card-padding: 44px;

  --padding-form-input: 14px;

  --margin-bottom-card: 20px;
  --card-margin-bottom: 20px;

  --padding-test-notice-vertical: 12px;
  --padding-test-notice-horizontal: 18px;


  /* Controls */
  --submit-btn-height: 56px;
  --checkbox-size: 20px;

  --opacity-placeholder: 0.5;


  /* Shadow */
  --box-shadow-card:
    0 2px 4px rgba(28, 32, 50, 0.025),
    0 18px 55px rgba(28, 32, 50, 0.09);
}



/* ==========================================================
   2. PAGE BACKGROUND
   ========================================================== */

html {
  min-height: 100%;
  background: var(--scio-bg);
}


body {
  min-height: 100vh;

  margin: 0;
  padding: 0 16px 64px;

  font-family: var(--font-family);

  color: var(--scio-text);

  background:
    radial-gradient(
      circle at 10% 0%,
      rgba(229, 139, 69, 0.10),
      transparent 32%
    ),
    radial-gradient(
      circle at 100% 90%,
      rgba(39, 43, 67, 0.06),
      transparent 36%
    ),
    var(--scio-bg);

  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}



/* ==========================================================
   3. CONTAINER
   ========================================================== */

.container {
  width: min(var(--container-width), 100%);

  margin-left: auto;
  margin-right: auto;

  padding-top: 52px;
}



/* ==========================================================
   4. MAIN CARD
   ========================================================== */

.card {
  position: relative;

  overflow: hidden;

  background: var(--scio-white);

  border: 1px solid rgba(39, 43, 67, 0.07);

  border-radius: 20px;

  box-shadow:
    0 2px 4px rgba(28, 32, 50, 0.025),
    0 18px 55px rgba(28, 32, 50, 0.09);

  text-align: left;
}


/* Scio orange line across top */

.card::before {
  content: "";

  position: absolute;

  top: 0;
  left: 0;

  width: 100%;
  height: 4px;

  background: var(--scio-orange);

  z-index: 5;
}



/* ==========================================================
   5. HEADER + SCIO LOGO
   ========================================================== */

.form-header {
  position: relative;

  text-align: left;

  padding-top: 94px;
}


/*
   Logo is loaded directly from Scio's CDN.
   No extra HTML element is required.
*/

.form-header::before {
  content: "";

  position: absolute;

  top: 5px;
  right: 0;

  width: 145px;
  height: 65px;

  background-image:
    url("https://cdn.prod.website-files.com/65a109e99c150dee93f0a5c3/6a8c16c49db9087ca3ce322b_SCIO%20logo%20full%20dark%20(2)%20(5).png");

  background-repeat: no-repeat;
  background-position: right center;
  background-size: contain;
}


.form-header h1 {
  margin-top: 0;
  margin-bottom: 0;

  max-width: 540px;

  color: var(--scio-navy);

  font-size: 34px;

  font-weight: 650;

  line-height: 1.08;

  letter-spacing: -0.035em;
}


.form-header p {
  max-width: 54ch;

  margin-top: 15px;
  margin-bottom: 0;

  color: var(--scio-muted);

  font-size: 15px;

  line-height: 1.65;
}



/* ==========================================================
   6. FORM BODY
   ========================================================== */

.inputs-wrapper {
  padding-top: 34px;
  padding-bottom: 28px;
}


.form-group {
  margin-bottom: 10px;
}



/* ==========================================================
   7. LABELS
   ========================================================== */

form label {
  display: block;

  padding-bottom: 8px;

  color: #34384d;

  font-weight: 600;

  line-height: 1.4;

  letter-spacing: -0.005em;
}



/* Required marker */

form label span,
.required {
  color: var(--scio-orange);
}



/* ==========================================================
   8. TEXT INPUTS / EMAIL / NUMBER
   ========================================================== */

form .form-input,
form select,
.select-input {
  box-sizing: border-box;

  transition:
    border-color 160ms ease,
    box-shadow 160ms ease,
    background-color 160ms ease,
    transform 160ms ease;
}


form .form-input {
  min-height: 50px;

  background: var(--scio-white);

  border: 1px solid var(--scio-border);

  border-radius: 10px;

  color: var(--scio-text);

  box-shadow:
    0 1px 2px rgba(25, 28, 44, 0.025);
}


form .form-input:hover,
.select-input:hover {
  border-color: var(--scio-border-hover);
}


form .form-input:focus,
form textarea:focus,
form input:focus,
form select:focus {
  outline: none;

  border-color: var(--scio-orange);

  box-shadow:
    0 0 0 4px rgba(229, 139, 69, 0.12),
    0 1px 2px rgba(25, 28, 44, 0.03);
}


.select-input:focus-within {
  border-color: var(--scio-orange);

  box-shadow:
    0 0 0 4px rgba(229, 139, 69, 0.12);
}



/* ==========================================================
   9. PLACEHOLDERS
   ========================================================== */

::placeholder {
  color: #989aa6;

  opacity: 1;
}



/* ==========================================================
   10. TEXTAREA
   ========================================================== */

form textarea.form-input {
  min-height: 120px;

  line-height: 1.55;

  resize: vertical;
}



/* ==========================================================
   11. SELECT / DROPDOWN
   ========================================================== */

form select,
.select-input {
  cursor: pointer;
}



/* ==========================================================
   12. CV / FILE UPLOAD
   ========================================================== */

.file-input-wrapper .form-input {
  min-height: 70px;

  padding: 10px;

  background: #fafaf8;

  border: 1px dashed #c6c7ce;

  border-radius: 11px;

  transition:
    border-color 160ms ease,
    background-color 160ms ease,
    box-shadow 160ms ease;
}


.file-input-wrapper .form-input:hover {
  background: #fffaf6;

  border-color: rgba(229, 139, 69, 0.75);
}


.file-input-wrapper .form-input:focus-within {
  border-color: var(--scio-orange);

  box-shadow:
    0 0 0 4px rgba(229, 139, 69, 0.10);
}


input[type="file"] {
  cursor: pointer;

  color: #737685;

  font-family: var(--font-family);
}


input[type="file"]::file-selector-button {
  border: 0;

  border-radius: 8px;

  background: var(--scio-navy);

  color: #ffffff;

  padding: 11px 16px;

  margin-right: 14px;

  font-family: var(--font-family);

  font-size: 13px;
  font-weight: 600;

  cursor: pointer;

  transition:
    background-color 150ms ease,
    transform 150ms ease,
    box-shadow 150ms ease;
}


input[type="file"]::file-selector-button:hover {
  background: var(--scio-navy-hover);

  transform: translateY(-1px);

  box-shadow:
    0 5px 14px rgba(39, 43, 67, 0.20);
}



/* ==========================================================
   13. CHECKBOXES
   ========================================================== */

input[type="checkbox"] {
  width: 20px;
  height: 20px;

  margin-right: 9px;

  accent-color: var(--scio-orange);

  cursor: pointer;
}


input[type="checkbox"]:focus {
  outline: none;

  box-shadow:
    0 0 0 4px rgba(229, 139, 69, 0.12);
}



/* ==========================================================
   14. RADIO BUTTONS
   ========================================================== */

input[type="radio"] {
  width: 19px;
  height: 19px;

  margin-right: 8px;

  accent-color: var(--scio-orange);

  cursor: pointer;
}



/* ==========================================================
   15. CHECKBOX / RADIO OPTION TEXT
   ========================================================== */

.form-group label:has(input[type="checkbox"]),
.form-group label:has(input[type="radio"]) {
  color: #464a5c;

  font-weight: 400;

  line-height: 1.55;
}



/* ==========================================================
   16. LINKS
   ========================================================== */

a {
  color: var(--scio-orange-hover);

  text-decoration-line: underline;
  text-decoration-thickness: 1px;
  text-underline-offset: 3px;

  transition: color 150ms ease;
}


a:hover {
  color: #b85f24;
}



/* ==========================================================
   17. SUBMIT BUTTON
   ========================================================== */

#submit-btn {
  min-height: 56px;

  border: 0;

  border-radius: 11px;

  background: var(--scio-orange);

  color: #ffffff;

  font-family: var(--font-family);

  font-size: 15px;
  font-weight: 650;

  letter-spacing: 0.005em;

  cursor: pointer;

  box-shadow:
    0 8px 22px rgba(229, 139, 69, 0.24);

  transition:
    transform 160ms ease,
    box-shadow 160ms ease,
    background-color 160ms ease,
    opacity 160ms ease;
}


#submit-btn:hover {
  opacity: 1;

  background: var(--scio-orange-hover);

  transform: translateY(-1px);

  box-shadow:
    0 12px 28px rgba(229, 139, 69, 0.30);
}


#submit-btn:active {
  transform: translateY(0);

  box-shadow:
    0 5px 14px rgba(229, 139, 69, 0.20);
}


#submit-btn:focus {
  outline: none;

  box-shadow:
    0 0 0 4px rgba(229, 139, 69, 0.18),
    0 8px 22px rgba(229, 139, 69, 0.24);
}



/* ==========================================================
   18. ERRORS
   ========================================================== */

.error-show,
.error-message {
  color: var(--scio-error);

  padding-top: 7px;

  font-size: 12px;

  line-height: 1.4;
}



/* ==========================================================
   19. TEST MODE NOTICE
   ========================================================== */

.test-notice {
  border-radius: 12px;

  border: 1px solid var(--color-test-notice-border);

  background: var(--color-test-notice-bg);

  color: var(--color-test-notice-text);

  box-shadow: none;
}



/* ==========================================================
   20. CUSTOM HTML SECTIONS
   Useful later for privacy text / "what happens next"
   ========================================================== */

.html-wrapper {
  color: #535768;

  line-height: 1.65;
}


.html-wrapper h2,
.html-wrapper h3 {
  color: var(--scio-navy);

  letter-spacing: -0.02em;
}


.html-wrapper p {
  color: #656978;

  line-height: 1.65;
}



/* ==========================================================
   21. OPTIONAL "INFO BOX" CLASS
   If you later add Custom HTML:
   <div class="scio-info">...</div>
   ========================================================== */

.scio-info {
  margin: 12px 0 22px;

  padding: 18px 20px;

  background: #f7f7f5;

  border: 1px solid #e5e5e1;

  border-left: 4px solid var(--scio-orange);

  border-radius: 10px;

  color: #565a69;

  font-size: 13px;

  line-height: 1.6;
}


.scio-info strong {
  color: var(--scio-navy);

  font-weight: 650;
}



/* ==========================================================
   22. OPTIONAL SECTION TITLE
   Custom HTML example:
   <div class="scio-section-title">Your experience</div>
   ========================================================== */

.scio-section-title {
  margin:
    28px
    0
    18px;

  padding-top: 25px;

  border-top: 1px solid #ecece8;

  color: var(--scio-navy);

  font-size: 18px;

  font-weight: 650;

  letter-spacing: -0.02em;
}



/* ==========================================================
   23. SUCCESS / THANK-YOU AREA
   ========================================================== */

.success,
.success-message {
  color: var(--scio-text);

  line-height: 1.6;
}



/* ==========================================================
   24. MOBILE
   ========================================================== */

@media (max-width: 680px) {

  :root {
    --font-size-header: 28px;

    --padding-card: 25px;
    --card-padding: 25px;

    --padding-container-top: 22px;
  }


  body {
    padding:
      0
      10px
      30px;
  }


  .container {
    padding-top: 22px;
  }


  .card {
    border-radius: 17px;
  }


  .form-header {
    padding-top: 78px;
  }


  .form-header::before {
    width: 115px;
    height: 52px;

    top: 3px;
  }


  .form-header h1 {
    font-size: 28px;

    line-height: 1.12;

    letter-spacing: -0.03em;
  }


  .form-header p {
    font-size: 14px;

    line-height: 1.6;
  }


  .inputs-wrapper {
    padding-top: 28px;
  }


  form .form-input {
    min-height: 50px;
  }


  input[type="file"]::file-selector-button {
    padding: 10px 12px;

    margin-right: 8px;
  }


  #submit-btn {
    min-height: 54px;

    font-size: 15px;
  }

}



/* ==========================================================
   25. VERY SMALL PHONES
   ========================================================== */

@media (max-width: 420px) {

  .form-header {
    padding-top: 68px;
  }


  .form-header::before {
    width: 102px;
    height: 45px;
  }


  .form-header h1 {
    font-size: 26px;
  }


  input[type="file"] {
    font-size: 12px;
  }

}

